svg.script:
var mode='pimpc', device='gpu', cpuCores=8, iter=0, playing=true, eqVis=false;
var N=8, RES_W=210;
function cpuTicks(){ return Math.ceil(N/cpuCores)+1; }
var SLIDER_MAX=3*(N+1)-1;
var workers=Array.prototype.slice.call(document.querySelectorAll('.worker'));
var slider=document.getElementById('iterSlider');
slider.max=SLIDER_MAX;

function btn(id,on){ document.getElementById(id).classList.toggle('on',on); }
function setMode(m){
  mode=m; btn('stdBtn',m==='standard'); btn('pimpcBtn',m==='pimpc');
  setIter(0); update();
}
function setDevice(d){ device=d; btn('cpuBtn',d==='cpu'); btn('gpuBtn',d==='gpu'); update(); }
function setCores(m){
  cpuCores=m;
  [1,2,4,8].forEach(function(n){ btn('c'+n+'Btn', n===m); });
  setIter(0); update();
}
function setIter(v){
  iter=+v; slider.value=iter;
  document.getElementById('iterVal').textContent=iter; update();
}
function togglePlay(){
  playing=!playing;
  document.querySelector('#playBtn text').textContent=playing?'Pause':'Play';
  btn('playBtn',playing);
}
function toggleEq(){
  eqVis=!eqVis;
  document.getElementById('eqPanel').classList.toggle('visible',eqVis);
  document.querySelector('#eqBtn text').textContent=eqVis?'Hide equations':'Show equations';
  btn('eqBtn',eqVis);
}

function setRbox(k,cls){
  var rb=document.getElementById('rbox'+k);
  var rt=document.getElementById('rtxt'+k);
  var rtb=document.getElementById('rtxtb'+k);
  if(!rb) return;
  rb.className.baseVal=cls;
  var active=cls==='rbox-active';
  rt.className.baseVal=active?'rtxt-active':'rtxt';
  if(rtb) rtb.className.baseVal=active?'rpk-active':'rpk';
}

/* FIX: status text is positioned by SVG attributes (text-anchor:end, x=SVG_W-30).
   JS only updates textContent — position never changes. */
function setStat(line1, line2){
  document.getElementById('statusTxt').textContent  = line1;
  document.getElementById('statusNote').textContent = line2;
}

function update(){
  var std=mode==='standard';
  document.getElementById('stdFlow').style.display   = std?'block':'none';
  document.getElementById('pimpcFlow').style.display = std?'none':'block';
  document.getElementById('legendGrp').style.display = std?'none':'block';
  document.getElementById('resGrp').style.display    = std?'none':'block';

  ['devLbl','cpuBtn','gpuBtn'].forEach(function(id){
    document.getElementById(id).style.opacity=std?0.3:1;
    document.getElementById(id).style.pointerEvents=std?'none':'auto';
  });
  var coreActive=!std&&device==='cpu';
  ['coresLbl','c1Btn','c2Btn','c4Btn','c8Btn'].forEach(function(id){
    document.getElementById(id).style.opacity=coreActive?1:0.3;
    document.getElementById(id).style.pointerEvents=coreActive?'auto':'none';
  });

  if(std){
    var stage=iter%N;
    for(var k=0;k<N;k++){
      var pos=(N-1)-k;
      if(pos===stage)    setRbox(k,'rbox-active');
      else if(pos<stage) setRbox(k,'rbox-done');
      else               setRbox(k,'rbox-wait');
    }
    document.getElementById('iterLbl').textContent=
      'RICCATI STAGE  (sweep '+(Math.floor(iter/N)+1)+')';
    setStat(
      'Standard ADMM — Riccati sweep k='+(N-1)+'→k=0  (serial by math, not hardware)',
      'Even with unlimited CPU cores, k must wait for k+1. The coupling is mathematical, not hardware.'
    );

  } else if(device==='gpu'){
    workers.forEach(function(w){
      w.classList.remove('active','inactive','done','alldone');
      w.classList.add('active');
    });
    document.getElementById('iterLbl').textContent='ADMM ITERATION i';
    setStat(
      'πMPC GPU — all '+N+' workers run simultaneously',
      'No mathematical coupling between stages. O(1) wall-clock per iteration, independent of N.'
    );

  } else {
    var TICKS=cpuTicks();
    var admm_i=Math.floor(iter/TICKS);
    var sub_t=iter%TICKS;
    var rounds=Math.ceil(N/cpuCores);
    var allDone=(sub_t===rounds);
    workers.forEach(function(w,k){
      w.classList.remove('active','inactive','done','alldone');
      if(allDone){ w.classList.add('alldone'); }
      else {
        var wr=Math.floor(k/cpuCores);
        if(wr<sub_t)       w.classList.add('done');
        else if(wr===sub_t) w.classList.add('active');
        else                w.classList.add('inactive');
      }
    });
    document.getElementById('iterLbl').textContent = allDone
      ? 'ADMM ITER '+admm_i+' complete ('+cpuCores+' cores, '+rounds+' round'+(rounds>1?'s':'')+')'
      : 'ADMM ITER '+admm_i+'  |  Round '+(sub_t+1)+'/'+rounds+'  ('+cpuCores+' core'+(cpuCores>1?'s':'')+')';
    var active_now=Math.min(cpuCores,N-sub_t*cpuCores);
    setStat(
      allDone
        ? 'πMPC CPU ('+cpuCores+' core'+(cpuCores>1?'s':'')+') — all '+N+' stages done'
        : 'πMPC CPU ('+cpuCores+' core'+(cpuCores>1?'s':'')+') — '+active_now+' worker'+(active_now>1?'s':'')+' in parallel',
      cpuCores>=N
        ? 'With '+cpuCores+' cores ≥ N: all workers run at once — identical to GPU.'
        : 'No mathematical coupling. With more cores, more stages run simultaneously.'
    );
  }

  if(!std){
    var ai=(device==='cpu')?Math.floor(iter/cpuTicks()):iter;
    var vX=Math.exp(-ai/6.2), vU=Math.exp(-ai/4.8), vD=Math.exp(-ai/7.5);
    document.getElementById('resX').setAttribute('width',RES_W*vX);
    document.getElementById('resU').setAttribute('width',RES_W*vU);
    document.getElementById('resD').setAttribute('width',RES_W*vD);
    document.getElementById('resXVal').textContent=vX<0.04?'✓':'↓';
    document.getElementById('resUVal').textContent=vU<0.04?'✓':'↓';
    document.getElementById('resDVal').textContent=vD<0.04?'✓':'↓';
  }
}

setInterval(function(){ if(playing) setIter((iter+1)%(SLIDER_MAX+1)); }, 680);

var svgEl=document.querySelector('svg');
document.querySelectorAll('[data-tip]').forEach(function(el){
  el.addEventListener('mousemove',function(ev){
    var pt=svgEl.createSVGPoint(); pt.x=ev.clientX; pt.y=ev.clientY;
    var sp=pt.matrixTransform(svgEl.getScreenCTM().inverse());
    var t=document.getElementById('tip'); t.style.display='block';
    t.setAttribute('transform','translate('+
      Math.min(sp.x+12,svgEl.viewBox.baseVal.width-530)+','+
      Math.max(sp.y-48,10)+')');
    document.getElementById('tipTxt').textContent=el.dataset.tip;
  });
  el.addEventListener('mouseleave',function(){
    document.getElementById('tip').style.display='none';
  });
});
update();
